<script setup>
import {onMounted,ref} from 'vue';import {request} from './service';
const layout=ref({home:[{id:'articles',enabled:true}],accent:'violet'}),profile=ref({}),moments=ref([]),albums=ref([]),anime=ref([]);
const accents={violet:'#81709b',forest:'#4e7c69',ocean:'#477d9f',rose:'#a46b80'};
const web=ref(null),error=ref('');
async function load(){try{const result=await request('/api/public/home');layout.value={accent:result.accent,home:result.modules.map(row=>({id:row.id,enabled:true}))};document.documentElement.style.setProperty('--lin-accent',accents[result.accent]||accents.violet);for(const row of result.modules){if(row.id==='profile')profile.value=row.data;if(row.id==='anime')anime.value=row.data.items;if(row.id==='moments')moments.value=row.data.items;if(row.id==='albums')albums.value=row.data.items;if(row.id==='web')web.value=row.data.selected;}error.value='';}catch{error.value='首页模块加载失败';}}
const imageUrl=item=>typeof item==='string'?item:item?.url;
onMounted(load);
</script>
<style scoped>
.home-posters{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:16px}.home-posters a{min-width:0;display:grid;align-content:start;gap:7px}.home-posters img{width:100%;aspect-ratio:2/3;object-fit:cover;border-radius:5px;background:var(--lin-line)}.home-posters strong{font-size:13px;line-height:1.5;color:var(--lin-text)}.home-posters small{font-size:10px}.home-extra iframe{display:block;width:100%;height:480px;border:1px solid var(--lin-line);background:white}
</style>
<template><div class="home-modules"><p v-if="error" role="alert">{{error}} <button @click="load">重试</button></p><template v-for="row in layout.home" :key="row.id"><template v-if="row.enabled"><slot v-if="row.id==='articles'"/><section v-else-if="row.id==='anime'" class="home-extra"><header><h2>本季放映</h2><a href="/anime">全部番剧 ↗</a></header><div v-if="anime.length" class="home-posters"><a v-for="item in anime" :key="item.id" href="/anime"><img :src="item.cover" :alt="item.title" loading="lazy"/><strong>{{item.title}}</strong><small>{{item.broadcast||'播出时间待定'}}</small></a></div><p v-else>本季度暂无可展示的番剧。</p></section><section v-else-if="row.id==='web'" class="home-extra"><header><h2>开发书架</h2><a v-if="web" :href="web.url" target="_blank" rel="noopener noreferrer">新窗口打开 ↗</a></header><template v-if="web"><h3>{{web.title}}</h3><p>{{web.description}}</p><iframe v-if="web.embeddable" :title="web.title" :src="web.url" loading="lazy" sandbox="allow-scripts allow-same-origin allow-popups" referrerpolicy="no-referrer"></iframe><p>{{web.embeddable?'若文档未显示，可使用新窗口打开。':'该来源使用新窗口阅读。'}}</p></template><p v-else>还没有公开的文档书签。</p></section><section v-else-if="row.id==='profile'" class="home-extra home-profile"><small>THE PERSON BEHIND THESE PAGES</small><h2>{{profile.name}}</h2><p>{{profile.bio||profile.tagline}}</p><a href="/about">关于这里 ↗</a></section><section v-else-if="row.id==='moments'" class="home-extra"><header><h2>最近的片刻</h2><a href="/moments">全部说说 ↗</a></header><div class="extra-grid"><article v-for="item in moments" :key="item.id"><time>{{item.created.slice(0,10)}}</time><p>{{item.content}}</p><img v-if="item.images?.[0]" :src="imageUrl(item.images[0])" alt="说说配图" loading="lazy"/></article><p v-if="!moments.length">还没有公开的片刻。</p></div></section><section v-else-if="row.id==='albums'" class="home-extra"><header><h2>光影收藏</h2><a href="/albums">翻开相册 ↗</a></header><div class="extra-grid"><a v-for="item in albums" :key="item.id" href="/albums"><img v-if="item.images?.[0]" :src="imageUrl(item.images[0])" :alt="item.title" loading="lazy"/><h3>{{item.title}}</h3></a><p v-if="!albums.length">相册正在慢慢填满。</p></div></section></template></template></div></template>
<style scoped>.home-modules{display:flex;flex-direction:column}.home-extra{width:calc(100% - 64px);max-width:1180px;margin:40px auto 20px;padding:28px 0;border-top:1px solid var(--lin-line)}.home-extra>header{display:flex;justify-content:space-between;align-items:center}.home-extra h2{font-size:26px;margin:12px 0 22px}.home-extra small,.home-extra time{font-size:10px;color:var(--lin-muted);letter-spacing:1.5px}.home-extra p{font-size:14px;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere}.home-extra a{font-size:12px;color:var(--lin-accent)}.extra-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.extra-grid img{width:100%;height:220px;object-fit:cover;border-radius:5px;margin-top:15px}.extra-grid article{padding:18px;background:var(--lin-paper);border:1px solid var(--lin-line);border-radius:7px}.extra-grid h3{font-size:14px;margin-top:12px}.home-profile{max-width:900px;text-align:center;padding:35px}.home-profile p{margin:15px 0 20px}@media(max-width:700px){.home-extra{width:calc(100% - 40px);margin-top:25px}.extra-grid{grid-template-columns:1fr}.home-extra h2{font-size:23px}.home-profile{padding:25px 0}}</style>
